{
  "implementation": "import collections

def solve(case):
    nodes = {n['id']: n for n in case['nodes']}
    children = {nid: [] for nid in nodes}
    for n in case['nodes']:
        pid = n['parent']
        if pid is not None:
            children[pid].append(n['id'])
    threshold = case['utility_threshold']

    # initial queue: descending depth, then stable by id
    queue = collections.deque(
        sorted(nodes.keys(), key=lambda x: (-nodes[x]['depth'], x))
    )
    in_queue = set(queue)
    removed = set()
    visit_order = []

    while queue:
        nid = queue.popleft()
        in_queue.discard(nid)
        if nid in removed:
            continue
        node = nodes[nid]
        visit_order.append(nid)
        # leaf: no unremoved children
        leaf = all(cid in removed for cid in children[nid])
        if node['removable'] and leaf and node['utility'] <= threshold:
            removed.add(nid)
            pid = node['parent']
            if pid is not None and pid not in removed:
                if pid not in in_queue:
                    queue.append(pid)
                    in_queue.add(pid)

    retained = [n['id'] for n in case['nodes'] if n['id'] not in removed]
    return {
        'retained_node_ids': retained,
        'visit_order': visit_order
    }"
